'use strict';

const cfg=window.DMO_CONFIG||{};
const sb=window.supabase?.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey,{auth:{persistSession:true,detectSessionInUrl:true}});
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const today=new Date(), initialMonth=`${today.getUTCFullYear()}-${String(today.getUTCMonth()+1).padStart(2,'0')}`;
let period=initialMonth, session=null, me=null, view='assign', state=emptyState(), busy=false;
let assignFilter={pending:false,responsible:''};
let rosterFilter={resp:'',q:''},rosterPicked=new Set(),rosterTyping=false;

function emptyState(){return{responsibles:[],centers:[],people:[],versions:[],lines:[],confirmations:[],validations:[],hrValidations:[],history:[],transfers:[],centerResponsibles:[],users:[],events:[]}}
const monthDate=()=>period+'-01';
const monthEnd=()=>{const[y,m]=period.split('-').map(Number);return new Date(Date.UTC(y,m,0)).toISOString().slice(0,10)};
const periodLabel=()=>new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(period+'-01T00:00:00Z'));
const fmtDate=v=>v?new Date(v).toLocaleString('es-AR',{dateStyle:'short',timeStyle:'short'}):'—';
const roleLabel=()=>({rrhh:'RRHH',responsable:'Responsable',administrador:'Administrador de costos'})[me?.role]||'Sin perfil';
const responsible=id=>state.responsibles.find(x=>x.id===id);
// Los dados de baja siguen en state.responsibles para mostrar nombres del historial, pero no se pueden elegir.
const liveResponsibles=()=>state.responsibles.filter(r=>r.active!==false);
const center=id=>state.centers.find(x=>x.id===id);
const activeCenters=()=>state.centers.filter(c=>c.active);
const person=id=>state.people.find(x=>x.id===id);
const activeInMonth=p=>p.start_date<=monthEnd()&&(!p.end_date||p.end_date>=monthDate());
const activePeople=()=>state.people.filter(activeInMonth);
const canManagePeople=()=>['rrhh','administrador'].includes(me?.role);
// Nómina: lista filtrada por área y por texto (nombre o legajo) para la asignación múltiple de responsables.
const rosterList=()=>{const q=norm(rosterFilter.q);return activePeople().filter(p=>(!rosterFilter.resp||owner(p)===rosterFilter.resp)&&(!q||norm(p.name).includes(q)||norm(p.id).includes(q)))};
const monthLabel=d=>new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(d.slice(0,7)+'-01T00:00:00Z'));
// Responsable principal en una fecha según el historial; en un mes, el vigente al cierre (o a la baja).
const ownerAt=(p,date)=>state.history.filter(h=>h.person_id===p.id&&h.valid_from<=date).sort((a,b)=>a.valid_from.localeCompare(b.valid_from)).at(-1)?.responsible_id||p.responsible_id;
const owner=p=>ownerAt(p,p.end_date&&p.end_date<monthEnd()?p.end_date:monthEnd());
const canAssign=p=>!hrValidated()&&(me?.role==='administrador'||(me?.role==='responsable'&&owner(p)===me.responsible_id));
function currentVersion(personId,date=monthEnd()){return state.versions.filter(v=>v.person_id===personId&&v.valid_from<=date&&(!v.valid_to||v.valid_to>=date)).sort((a,b)=>a.valid_from.localeCompare(b.valid_from)).at(-1)}
const usesInactiveCenter=id=>allocation(id).some(a=>center(a.center_id)&&!center(a.center_id).active);
function allocation(personId){const v=currentVersion(personId);const ord=x=>center(x.center_id)?.sort_order??0;return v?state.lines.filter(x=>x.version_id===v.id).sort((a,b)=>ord(a)-ord(b)||a.center_id.localeCompare(b.center_id)).map(x=>({...x,version:v})):[]}
const total=id=>allocation(id).reduce((s,x)=>s+Number(x.pct),0);
const complete=id=>allocation(id).length>0&&Math.abs(total(id)-100)<.001;
// Un centro puede tener más de un responsable: cualquiera de ellos confirma lo que el centro recibe.
const centerResps=centerId=>state.centerResponsibles.filter(x=>x.center_id===centerId).map(x=>x.responsible_id);
const centerHasResp=centerId=>centerResps(centerId).length>0;
const centerRespNames=centerId=>centerResps(centerId).map(id=>responsible(id)?.name).filter(Boolean).sort((a,b)=>a.localeCompare(b,'es'));
const ownsCenter=(centerId,rid=me?.responsible_id)=>!!rid&&centerResps(centerId).includes(rid);
// Una confirmación se mantiene en los meses siguientes mientras el porcentaje de ese centro no cambie,
// no haya un reingreso de por medio y el centro no haya cambiado de responsable (salvo en meses cerrados).
const confirmation=(personId,centerId)=>{const v=currentVersion(personId);if(!v)return;const pctOf=vid=>state.lines.find(l=>l.version_id===vid&&l.center_id===centerId)?.pct,cur=pctOf(v.id),same=x=>x!=null&&Math.abs(Number(x)-Number(cur))<1e-6;if(cur==null)return;const startM=person(personId).start_date.slice(0,7)+'-01',since=center(centerId)?.responsible_since;return state.confirmations.filter(x=>x.period<=monthDate()&&x.person_id===personId&&x.center_id===centerId&&(!since||hrValidated()||new Date(x.confirmed_at)>=new Date(since))).sort((a,b)=>b.period.localeCompare(a.period)).find(x=>{const cv=state.versions.find(y=>y.id===x.version_id);return cv&&cv.valid_from<=v.valid_from&&(cv.valid_from>=startM||v.valid_from<startM)&&same(pctOf(cv.id))&&state.versions.filter(y=>y.person_id===personId&&y.valid_from>cv.valid_from&&y.valid_from<=v.valid_from).every(y=>same(pctOf(y.id)))})};
const confirmedBadge=c=>badge(c.period===monthDate()?'Confirmado':`Confirmado en ${new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(c.period+'T00:00:00Z'))}`,'ok');
function missingShared(personId){const p=person(personId);return allocation(personId).filter(x=>centerHasResp(x.center_id)&&!ownsCenter(x.center_id,owner(p))&&!confirmation(personId,x.center_id))}
function receivedShared(){if(me?.role!=='responsable')return[];return activePeople().flatMap(p=>allocation(p.id).filter(a=>owner(p)!==me.responsible_id&&ownsCenter(a.center_id)&&!ownsCenter(a.center_id,owner(p))).map(a=>({p,a,c:center(a.center_id)})))}
const validated=rid=>state.validations.some(x=>x.period===monthDate()&&x.responsible_id===rid);
const hrValidated=()=>state.hrValidations.some(x=>x.period===monthDate());
function myPrimary(){return activePeople().filter(p=>owner(p)===me?.responsible_id)}
// Transferencias: RRHH y el administrador ven todos los pedidos; un responsable sólo los que pidió él (lo filtra la política de RLS).
const pendingTransfers=()=>state.transfers.filter(t=>t.status==='pendiente');
const transferOf=personId=>pendingTransfers().find(t=>t.person_id===personId);
const myTransfers=()=>state.transfers.filter(t=>t.from_responsible_id===me?.responsible_id).sort((a,b)=>String(b.requested_at).localeCompare(String(a.requested_at)));
function responsibleReady(rid){const mine=activePeople().filter(p=>owner(p)===rid);const received=activePeople().flatMap(p=>allocation(p.id).filter(a=>owner(p)!==rid&&ownsCenter(a.center_id,rid)&&!ownsCenter(a.center_id,owner(p))).map(a=>({p,a})));return(mine.length>0||received.length>0)&&mine.every(p=>complete(p.id))}
const personIssues=p=>{const out=[];if(!allocation(p.id).length)out.push('Sin asignar');else if(!complete(p.id))out.push(`Suma ${total(p.id).toFixed(2)}%`);if(usesInactiveCenter(p.id))out.push('Tiene un centro dado de baja');return out};
const isPending=p=>personIssues(p).length>0;
function pendingDetail(rid,self=false){const r=responsible(rid),mine=activePeople().filter(p=>owner(p)===rid);const toComplete=mine.map(p=>({p,issues:personIssues(p)})).filter(x=>x.issues.length);const parts=[];if(toComplete.length)parts.push(`<h4>Asignaciones por completar</h4><ul>${toComplete.map(x=>`<li>${esc(x.p.name)} (${esc(x.p.id)}): ${esc(x.issues.join(' · '))}</li>`).join('')}</ul>`);if(!parts.length&&!validated(rid)&&!self)parts.push('<p>Tiene todo completo: sólo falta que toque <b>Validar todo el mes</b>.</p>');if(!parts.length)return'';if(self)return`<div class="pending-detail">${parts.join('')}</div>`;return`<details class="pending-detail"><summary>Ver qué falta</summary>${r?.email?`<p>Correo: <a href="mailto:${esc(r.email)}">${esc(r.email)}</a></p>`:''}${parts.join('')}</details>`}

function toast(text,error=false){const n=$('#toast');n.textContent=text;n.style.background=error?'#8f343b':'';n.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>n.hidden=true,4300)}
function badge(text,type=''){return`<span class="badge ${type}">${esc(text)}</span>`}
function initials(name){return String(name).split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function head(title,lead,actions=''){return`<div class="heading"><div><h1>${esc(title)}</h1><p class="lead">${esc(lead)}</p></div><div class="actions">${actions}</div></div>`}
function modal(title,body,foot=''){const d=$('#modal');d.innerHTML=`<div class="modalhead"><h2>${esc(title)}</h2><button id="modalClose" class="close" aria-label="Cerrar">×</button></div><div class="modalbody">${body}</div>${foot?`<div class="modalfoot">${foot}</div>`:''}`;$('#modalClose').onclick=()=>d.close();d.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>d.close());d.showModal()}
async function run(promise){if(busy)throw new Error('Hay otra operación en curso.');busy=true;try{const{data,error}=await promise;if(error)throw error;return data}finally{busy=false}}
async function audit(type,description){const{error}=await sb.from('audit_events').insert({actor_email:session.user.email.toLowerCase(),event_type:type,description});if(error)console.warn(error.message)}

async function boot(){
  if(!sb){showLoginError('Falta la configuración de Supabase.');return}
  $('#loginForm').onsubmit=sendLogin;$('#logout').onclick=()=>sb.auth.signOut();$('#myPassword').onclick=openMyPassword;$('#periodFilter').onchange=e=>{period=e.target.value;render()};
  // Supabase avisa solo al volver a la pestaña y al renovar el token: si sigue siendo la misma persona, sólo se actualiza la sesión, sin recargar la pantalla.
  sb.auth.onAuthStateChange((_event,newSession)=>{if(newSession&&me&&session&&newSession.user.id===session.user.id){session=newSession;return}setTimeout(()=>acceptSession(newSession),0)});
  const{data}=await sb.auth.getSession();await acceptSession(data.session);
}
async function sendLogin(e){e.preventDefault();const email=$('#loginEmail').value.trim().toLowerCase(),password=$('#loginPassword').value,box=$('#loginMessage');box.className='login-message';box.textContent='Ingresando…';const{error}=await sb.auth.signInWithPassword({email,password});if(error){box.classList.add('error');box.textContent=/invalid login credentials/i.test(error.message)?'Correo o contraseña incorrectos.':error.message;return}$('#loginPassword').value='';box.textContent=''}
function showLoginError(text){$('#login').hidden=false;$('#secureApp').hidden=true;const box=$('#loginMessage');box.textContent=text;box.className='login-message error'}
async function acceptSession(next){session=next;if(!session){me=null;state=emptyState();$('#login').hidden=false;$('#secureApp').hidden=true;return}const email=session.user.email.toLowerCase();const{data,error}=await sb.from('app_users').select('*').eq('email',email).eq('active',true).maybeSingle();if(error||!data){await sb.auth.signOut();showLoginError('Tu usuario no está habilitado en la aplicación. Pedile acceso a RRHH o al administrador.');return}me=data;$('#login').hidden=true;$('#secureApp').hidden=false;view=me.role==='responsable'?'assign':'roster';await loadData()}
// Supabase entrega como máximo 1000 filas por consulta: se piden páginas hasta completar el total.
async function fetchAll(build){const out=[];for(;;){const{data,error,count}=await build().range(out.length,out.length+999);if(error)return{error};out.push(...data);if(!data.length||(count!=null?out.length>=count:data.length<1000))return{data:out}}}
async function loadData(){
  $('#app').innerHTML='<div class="loading">Cargando información…</div>';
  const page=(table,order,filter=q=>q)=>fetchAll(()=>order.reduce((q,c)=>q.order(c),filter(sb.from(table).select('*',{count:'exact'}))));
  const queries=[page('responsibles',['name','id']),page('centers',['sort_order','id']),page('people',['name','id']),page('assignment_versions',['valid_from','id']),page('assignment_lines',['id']),page('shared_confirmations',['period','person_id','center_id']),page('monthly_validations',['period','responsible_id']),page('hr_validations',['period']),page('responsible_history',['person_id','valid_from']),page('transfer_requests',['requested_at']),page('center_responsibles',['center_id','responsible_id']),sb.from('audit_events').select('*').order('created_at',{ascending:false}).limit(200)];
  if(canManagePeople())queries.push(page('app_users',['display_name','email']));
  const results=await Promise.all(queries);const failed=results.find(x=>x.error);if(failed){showFatal(failed.error.message);return}
  [state.responsibles,state.centers,state.people,state.versions,state.lines,state.confirmations,state.validations,state.hrValidations,state.history,state.transfers,state.centerResponsibles,state.events,state.users]=results.map(x=>x.data||[]);render();
}
function showFatal(message){$('#app').innerHTML=`<div class="notice danger"><b>No se pudo cargar la aplicación.</b><br>${esc(message)}<br><br>Verificá que se haya ejecutado <code>supabase/setup.sql</code>.</div>`}

const NAV={rrhh:[['roster','▤','Nómina'],['centers','⌂','Centros'],['users','＠','Accesos'],['assign','％','Asignaciones'],['transfers','⇄','Transferencias'],['validation','✓','Cierre mensual'],['export','⇩','Exportar'],['history','◷','Historial']],responsable:[['assign','％','Mis colaboradores'],['validation','✓','Validación mensual']],administrador:[['roster','▤','Nómina'],['centers','⌂','Centros'],['users','＠','Accesos'],['assign','％','Asignaciones'],['transfers','⇄','Transferencias'],['validation','✓','Cierre mensual'],['export','⇩','Exportar'],['history','◷','Historial']]};
function render(){if(me.must_change_password){renderForcedPassword();return}const nav=NAV[me.role];if(!nav.some(x=>x[0]===view))view=nav[0][0];$('#nav').innerHTML=nav.map(x=>`<button class="navbtn ${view===x[0]?'active':''}" data-view="${x[0]}"><i>${x[1]}</i>${x[2]}${x[0]==='transfers'&&pendingTransfers().length?`<span class="count">${pendingTransfers().length}</span>`:''}</button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('#periodFilter').value=period;$('#periodAside').textContent=periodLabel();$('#rolePill').textContent=roleLabel();$('#signedUser').textContent=session.user.email;const fn={roster:rosterView,centers:centersView,users:usersView,assign:assignView,transfers:transfersView,validation:validationView,export:exportView,history:historyView}[view];$('#app').innerHTML=fn();bind()}
function passwordFields(forced){return`${forced?'':'<label class="field">Contraseña actual<input id="pwdCurrent" type="password" autocomplete="current-password"></label>'}<label class="field">Nueva contraseña<input id="pwdNew" type="password" autocomplete="new-password"></label><label class="field">Repetir nueva contraseña<input id="pwdRepeat" type="password" autocomplete="new-password"></label><p class="small">Mínimo 8 caracteres.</p><div id="pwdError" class="error"></div>`}
async function saveOwnPassword(forced){const next=$('#pwdNew').value;if(next.length<8){$('#pwdError').textContent='La contraseña debe tener al menos 8 caracteres.';return false}if(next!==$('#pwdRepeat').value){$('#pwdError').textContent='Las contraseñas no coinciden.';return false}try{await run(sb.rpc('change_my_password',{current_password:forced?'':$('#pwdCurrent').value,new_password:next}));me.must_change_password=false;await audit('access','Cambio de contraseña propia');return true}catch(e){$('#pwdError').textContent=e.message;return false}}
function renderForcedPassword(){$('#nav').innerHTML='';$('#periodAside').textContent=periodLabel();$('#rolePill').textContent=roleLabel();$('#signedUser').textContent=session.user.email;$('#app').innerHTML=head('Elegí tu contraseña','Antes de continuar, reemplazá la contraseña inicial por una que sólo sepas vos.')+`<section class="panel" style="max-width:520px"><div class="panelbody">${passwordFields(true)}<button class="btn primary" id="saveForcedPwd">Guardar contraseña</button></div></section>`;$('#saveForcedPwd').onclick=async()=>{if(await saveOwnPassword(true)){toast('Contraseña guardada.');render()}}}
function openMyPassword(){if(me?.must_change_password)return;modal('Cambiar mi contraseña',passwordFields(false),`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveMyPwd">Guardar</button>`);$('#saveMyPwd').onclick=async()=>{if(await saveOwnPassword(false)){$('#modal').close();toast('Contraseña actualizada.')}}}
function randomPassword(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789',v=crypto.getRandomValues(new Uint32Array(10));return[...v].map(x=>chars[x%chars.length]).join('')}
const canSetPassword=u=>me?.role==='administrador'||(me?.role==='rrhh'&&u.role!=='administrador');
const initialPasswordField=()=>`<label class="field">Contraseña inicial<span style="display:flex;gap:8px;margin-top:6px"><input id="initPwd" type="text" autocomplete="off" style="flex:1"><button type="button" class="btn" id="genPwd">Generar</button></span></label><p class="small">Mínimo 8 caracteres. Pasásela a la persona por un medio privado: al ingresar, la aplicación le va a pedir que la cambie.</p>`;
function bindInitialPassword(){$('#genPwd').onclick=()=>{$('#initPwd').value=randomPassword()}}
function readInitialPassword(){const pwd=$('#initPwd').value;if(pwd.length<8){$('#formError').textContent='La contraseña inicial debe tener al menos 8 caracteres.';return null}return pwd}
function openSetPassword(email){const u=state.users.find(x=>x.email===email);if(!u||!canSetPassword(u))return;modal('Contraseña de acceso',`<p><b>${esc(u.display_name)}</b> · ${esc(u.email)}</p>${initialPasswordField()}${u.password_set_at?'<p class="small">Si la persona tenía una sesión abierta, se va a cerrar.</p>':''}<div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveInitPwd">Guardar</button>`);bindInitialPassword();$('#saveInitPwd').onclick=async()=>{const pwd=readInitialPassword();if(!pwd)return;try{await run(sb.rpc('set_user_password',{target_email:email,new_password:pwd}));$('#modal').close();await loadData();toast('Contraseña guardada.')}catch(e){$('#formError').textContent=e.message}}}

function rosterView(){const list=activePeople(),shown=rosterList(),manage=canManagePeople();return head('Nómina de personal',`RRHH mantiene altas, bajas y responsable principal. Período: ${periodLabel()}.`,`<a class="btn" href="assets/Plantilla_Importacion_Personal_DMO.xlsx" download>Descargar plantilla</a><button class="btn" id="importRoster" ${state.people.length?'disabled':''}>Importación inicial</button>${me.role==='administrador'&&state.people.length?'<button class="btn danger" id="clearTest">Vaciar datos de prueba</button>':''}<button class="btn primary" id="newHire">＋ Nuevo ingreso</button>`)+closedNotice()+`<div class="cards"><div class="card"><span>Personas del período</span><strong>${list.length}</strong><small>Con vigencia en el mes</small></div><div class="card"><span>Activas al cierre</span><strong>${list.filter(p=>!p.end_date||p.end_date>=monthEnd()).length}</strong><small>Al ${monthEnd().split('-').reverse().join('/')}</small></div><div class="card"><span>Altas del mes</span><strong>${state.people.filter(p=>p.start_date.startsWith(period)).length}</strong></div><div class="card"><span>Bajas del mes</span><strong>${state.people.filter(p=>p.end_date?.startsWith(period)).length}</strong></div></div><section class="panel"><div class="panelhead"><div><h2>Personal vigente</h2><p>Las bajas conservan todo el historial.</p></div>${badge(hrValidated()?'Mes cerrado':'Mes abierto',hrValidated()?'ok':'pending')}</div>${manage?rosterTools(shown,list.length):''}<div class="tablewrap"><table><thead><tr>${manage?`<th class="pick"><input type="checkbox" id="pickAll" ${shown.length&&shown.every(p=>rosterPicked.has(p.id))?'checked':''}></th>`:''}<th>Legajo y nombre</th><th>Vigencia</th><th>Responsable principal</th><th>Asignación</th><th>Acciones</th></tr></thead><tbody>${shown.map(p=>`<tr>${manage?`<td class="pick"><input type="checkbox" data-pick="${esc(p.id)}" ${rosterPicked.has(p.id)?'checked':''}></td>`:''}<td><b>${esc(p.name)}</b><br><span class="small">${esc(p.id)}</span></td><td>Alta:${p.start_date.split('-').reverse().join('/')}<br>${p.end_date?'Baja: '+p.end_date.split('-').reverse().join('/'):badge('Activa','ok')}</td><td>${esc(responsible(owner(p))?.name||'Sin responsable')}</td><td>${complete(p.id)?badge('100%','ok'):badge(`${Number(total(p.id)).toFixed(2)}%`,'bad')}</td><td><div class="actions"><button class="btn" data-owner="${esc(p.id)}">Cambiar responsable</button><button class="btn" data-end="${esc(p.id)}">${p.end_date?'Modificar baja':'Registrar baja'}</button></div></td></tr>`).join('')||`<tr><td colspan="${manage?6:5}" class="empty">${list.length?'Ninguna persona coincide con el filtro.':'No hay personas cargadas.'}</td></tr>`}</tbody></table></div></section>`}

// Barra de filtros y de asignación múltiple de responsable (sólo RRHH y administrador).
function rosterTools(shown,total){const n=rosterPicked.size;return`<div class="panelhead filters"><select id="rosterResp"><option value="">Todos los responsables</option>${liveResponsibles().map(r=>`<option value="${r.id}" ${rosterFilter.resp===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><input id="rosterSearch" placeholder="Buscar por nombre o legajo" value="${esc(rosterFilter.q)}"><span class="small">${shown.length} de ${total} personas</span>${n?`${badge(`${n} seleccionada${n===1?'':'s'}`,'ok')}<button class="btn primary" id="bulkOwner">Asignar responsable</button><button class="btn" id="pickNone">Limpiar selección</button>`:''}</div>`}

function updateRosterPicks(){const tb=document.querySelector('.panelhead.filters');if(!tb){render();return}const shown=rosterList();tb.outerHTML=rosterTools(shown,activePeople().length);const pa=$('#pickAll');if(pa)pa.checked=shown.length>0&&shown.every(p=>rosterPicked.has(p.id));bindRosterToolbar()}
function bindRosterToolbar(){$('#rosterResp')&&($('#rosterResp').onchange=e=>{rosterFilter.resp=e.target.value;rosterTyping=false;render()});if($('#rosterSearch')){const el=$('#rosterSearch');el.oninput=()=>{rosterFilter.q=el.value;rosterTyping=true;render()}};$('#pickNone')&&($('#pickNone').onclick=()=>{rosterPicked.clear();document.querySelectorAll('[data-pick]').forEach(c=>{c.checked=false});updateRosterPicks()});$('#bulkOwner')&&($('#bulkOwner').onclick=openBulkOwner)}
const closedNotice=()=>hrValidated()?`<div class="notice"><b>${esc(periodLabel().replace(/^./,c=>c.toUpperCase()))} está cerrado.</b> RRHH validó la nómina: no se pueden hacer cambios que alcancen este mes${canManagePeople()?' salvo que se reabra desde Cierre mensual':''}.</div>`:'';
function allocationHtml(id){const rows=allocation(id);if(!rows.length)return badge('Sin asignar','bad');return`<div class="allocation">${rows.map(a=>`<div><small>${esc(center(a.center_id)?.name||a.center_id)}${center(a.center_id)&&!center(a.center_id).active?' (de baja)':''}</small><b>${Number(a.pct).toFixed(Number(a.pct)%1?2:0)}%</b></div>`).join('')}<div class="bar">${rows.map(a=>`<i style="width:${Number(a.pct)}%"></i>`).join('')}</div></div>`}
function assignView(){let list=me.role==='responsable'?myPrimary():activePeople();const all=list.length;if(me.role!=='responsable'&&assignFilter.responsible)list=list.filter(p=>owner(p)===assignFilter.responsible);if(assignFilter.pending)list=list.filter(isPending);return head(me.role==='responsable'?'Mis colaboradores':'Asignaciones','La persona responsable principal carga el reparto completo; el responsable receptor confirma su parte.')+closedNotice()+`<section class="panel"><div class="panelhead"><div><h2>${me.role==='responsable'?esc(responsible(me.responsible_id)?.name||'Responsable'):'Todas las personas'}</h2><p>Cada distribución debe sumar exactamente 100%.${list.length!==all?` Mostrando ${list.length} de ${all}.`:''}</p></div><div class="filters">${me.role!=='responsable'?`<select id="filterResponsible"><option value="">Todos los responsables</option>${liveResponsibles().map(r=>`<option value="${r.id}" ${assignFilter.responsible===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`:''}<select id="filterPending"><option value="">Todas las personas</option><option value="1" ${assignFilter.pending?'selected':''}>Solo pendientes</option></select></div></div><div class="tablewrap"><table><thead><tr><th>Persona</th><th>Distribución</th><th>Estado</th><th>Responsable</th><th>Acción</th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="person"><span class="circle">${initials(p.name)}</span><div class="name"><b>${esc(p.name)}</b><small>${esc(p.id)}</small></div></div></td><td>${allocationHtml(p.id)}</td><td>${usesInactiveCenter(p.id)?badge('Centro dado de baja: reasignar','bad'):!complete(p.id)?badge('Falta completar','bad'):badge('Lista','ok')+(missingShared(p.id).length?' '+badge(missingShared(p.id).length+' sin confirmar'):'')}${transferOf(p.id)?' '+badge('Transferencia pedida','pending'):''}</td><td>${esc(responsible(owner(p))?.name||'—')}</td><td><div class="actions">${canAssign(p)?`<button class="btn" data-assign="${esc(p.id)}">Editar asignación</button>`:`<button class="btn" data-detail="${esc(p.id)}">Ver</button>`}${transferButton(p)}</div></td></tr>`).join('')||`<tr><td colspan="5" class="empty">${list.length!==all?'No hay personas con este filtro.':'No hay personas para mostrar.'}</td></tr>`}</tbody></table></div></section>${me.role==='responsable'?sharedPanel()+transferPanel():''}`}
function sharedPanel(){const rows=receivedShared();return`<section class="panel"><div class="panelhead"><div><h2>Dedicaciones recibidas</h2><p>Quedan a la vista para que las revises. Confirmar es opcional: ya no frena tu validación ni el cierre del mes.</p></div></div>${rows.map(x=>`<div class="listrow"><div><b>${esc(x.p.name)}</b><p>${esc(x.c.name)} · ${Number(x.a.pct).toFixed(2)}%</p></div>${confirmation(x.p.id,x.c.id)?confirmedBadge(confirmation(x.p.id,x.c.id)):hrValidated()?badge('Sin confirmar'):`<button class="btn primary" data-confirm="${esc(x.p.id)}|${esc(x.c.id)}">Confirmar</button>`}</div>`).join('')||'<div class="empty">No recibiste dedicaciones de otros responsables.</div>'}</section>`}

// Pantalla de RRHH: aprobar o rechazar los pedidos de transferencia de los responsables.
function transfersView(){const pend=pendingTransfers(),done=state.transfers.filter(t=>t.status!=='pendiente').sort((a,b)=>String(b.resolved_at).localeCompare(String(a.resolved_at))).slice(0,40),who=id=>esc(responsible(id)?.name||'—');return head('Transferencias','Un responsable pide que una persona deje de estar a su cargo. Hablá con el responsable nuevo antes de aprobar.')+`<section class="panel"><div class="panelhead"><div><h2>${pend.length} ${pend.length===1?'pedido pendiente':'pedidos pendientes'}</h2><p>Mientras el pedido está pendiente no cambia nada: la persona sigue a cargo de quien la pidió.</p></div></div>${pend.map(t=>`<div class="listrow"><div class="grow"><b>${esc(person(t.person_id)?.name||t.person_id)}</b><p>${who(t.from_responsible_id)} → propone <b>${who(t.suggested_responsible_id)}</b> · pedido el ${esc(fmtDate(t.requested_at))} por ${esc(t.requested_by)}</p><p class="reason">${esc(t.reason)}</p></div><div class="actions"><button class="btn primary" data-transfer-ok="${esc(t.id)}">Aprobar</button><button class="btn danger" data-transfer-no="${esc(t.id)}">Rechazar</button></div></div>`).join('')||'<div class="empty">No hay pedidos pendientes.</div>'}</section>${done.length?`<section class="panel"><div class="panelhead"><div><h2>Pedidos resueltos</h2><p>Los últimos ${done.length}.</p></div></div>${done.map(t=>`<div class="listrow"><div class="grow"><b>${esc(person(t.person_id)?.name||t.person_id)}</b><p>${t.status==='aprobada'?`Pasó de ${who(t.from_responsible_id)} a <b>${who(t.final_responsible_id)}</b> desde ${esc(t.effective_from?monthLabel(t.effective_from):'—')}`:t.status==='rechazada'?`Rechazado: sigue a cargo de ${who(t.from_responsible_id)}`:`Cancelado por ${esc(t.resolved_by||'—')}`}</p>${t.resolution_note?`<p class="reason">${esc(t.resolution_note)}</p>`:''}</div>${badge(t.status==='aprobada'?'Aprobada':t.status==='rechazada'?'Rechazada':'Cancelada',t.status==='aprobada'?'ok':t.status==='rechazada'?'bad':'')}</div>`).join('')}</section>`:''}`}
// Al aprobar se elige el responsable definitivo y el mes: resolve_transfer borra el reparto desde ese mes y mueve el historial.
function openResolveTransfer(id){const t=state.transfers.find(x=>x.id===id);if(!t)return;const p=person(t.person_id);modal(`Aprobar la transferencia de ${p?.name||t.person_id}`,`<p>${esc(responsible(t.from_responsible_id)?.name||'—')} pidió que esta persona deje de estar a su cargo:</p><p class="reason">${esc(t.reason)}</p><div class="split"><label class="field">Pasa a cargo de<select id="trResp">${liveResponsibles().filter(r=>r.id!==t.from_responsible_id).map(r=>`<option value="${r.id}" ${r.id===t.suggested_responsible_id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label class="field">Desde el mes<input id="trMonth" type="month" ${p?`min="${p.start_date.slice(0,7)}"`:''} ${p&&p.end_date?`max="${p.end_date.slice(0,7)}"`:''} value="${period}"></label></div><label class="field">Nota (opcional)<input id="trNote" placeholder="Ej.: hablado con los dos responsables"></label><div class="notice danger"><b>Se borra la distribución de centros desde ese mes.</b> El responsable nuevo la va a ver como «Falta completar» y la tiene que cargar. Los meses anteriores no se tocan.</div><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveTransfer">Aprobar y transferir</button>`);$('#saveTransfer').onclick=async()=>{const month=$('#trMonth').value;if(!/^\d{4}-\d{2}$/.test(month)){$('#formError').textContent='Indicá desde qué mes toma efecto.';return}try{await run(sb.rpc('resolve_transfer',{p_id:id,p_approve:true,p_final_responsible:$('#trResp').value,p_effective_from:month+'-01',p_note:$('#trNote').value.trim()||null}));$('#modal').close();await loadData();toast(`Transferencia aprobada desde ${monthLabel(month+'-01')}.`)}catch(e){$('#formError').textContent=e.message}}}
function openRejectTransfer(id){const t=state.transfers.find(x=>x.id===id);if(!t)return;modal('Rechazar el pedido',`<p><b>${esc(person(t.person_id)?.name||t.person_id)}</b> sigue a cargo de ${esc(responsible(t.from_responsible_id)?.name||'—')}.</p><label class="field">Motivo del rechazo<input id="trReject" placeholder="El responsable lo va a ver en la aplicación"></label><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn danger" id="doReject">Rechazar pedido</button>`);$('#doReject').onclick=async()=>{const note=$('#trReject').value.trim();if(!note){$('#formError').textContent='Escribí el motivo: el responsable lo va a ver.';return}try{await run(sb.rpc('resolve_transfer',{p_id:id,p_approve:false,p_final_responsible:null,p_effective_from:null,p_note:note}));$('#modal').close();await loadData();toast('Pedido rechazado.')}catch(e){$('#formError').textContent=e.message}}}

// Sólo el responsable principal pide la transferencia, y sólo él la puede cancelar mientras siga pendiente.
function transferButton(p){if(me?.role!=='responsable'||owner(p)!==me.responsible_id)return'';const t=transferOf(p.id);if(t)return`<button class="btn" data-transfer-cancel="${esc(t.id)}">Cancelar pedido</button>`;if(liveResponsibles().length<2)return'';return`<button class="btn" data-transfer-new="${esc(p.id)}">Ya no trabaja conmigo</button>`}
// El responsable ve acá en qué quedó cada pedido que hizo, incluida la nota de RRHH cuando lo rechaza.
function transferPanel(){const rows=myTransfers().slice(0,20);if(!rows.length)return'';const who=id=>esc(responsible(id)?.name||'—');return`<section class="panel"><div class="panelhead"><div><h2>Transferencias que pediste</h2><p>RRHH habla con el responsable nuevo antes de aprobar. Mientras el pedido esté pendiente, la persona sigue a tu cargo.</p></div></div>${rows.map(t=>`<div class="listrow"><div class="grow"><b>${esc(person(t.person_id)?.name||t.person_id)}</b><p>${t.status==='pendiente'?`Propusiste ${who(t.suggested_responsible_id)} · pedido el ${esc(fmtDate(t.requested_at))}`:t.status==='aprobada'?`Pasó a ${who(t.final_responsible_id)} desde ${esc(t.effective_from?monthLabel(t.effective_from):'—')}`:t.status==='rechazada'?`RRHH rechazó el pedido: sigue a tu cargo.`:'Cancelaste el pedido.'}</p>${t.resolution_note?`<p class="reason">${esc(t.resolution_note)}</p>`:''}</div>${t.status==='pendiente'?`<div class="actions">${badge('Pendiente','pending')}<button class="btn" data-transfer-cancel="${esc(t.id)}">Cancelar pedido</button></div>`:badge(t.status==='aprobada'?'Aprobada':t.status==='rechazada'?'Rechazada':'Cancelada',t.status==='aprobada'?'ok':t.status==='rechazada'?'bad':'')}</div>`).join('')}</section>`}
// El pedido no cambia nada todavía: no toca la asignación ni el mes, sólo queda a la espera de RRHH.
function openTransfer(id){const p=person(id),options=liveResponsibles().filter(r=>r.id!==owner(p));if(!options.length){toast('No hay otro responsable activo al que pasarla.',true);return}modal(`${p.name} ya no trabaja conmigo`,`<p>Esto no cambia nada todavía: RRHH recibe el pedido, habla con el responsable nuevo y decide desde qué mes toma efecto.</p><label class="field">¿A cargo de quién debería quedar?<select id="tnResp">${options.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><label class="field">Motivo<textarea id="tnReason" rows="3" placeholder="Ej.: pasó al sector de Compras en septiembre"></textarea></label><p class="small">Si se aprueba, la distribución de centros de esta persona se borra desde el mes que elija RRHH y la carga el responsable nuevo. Los meses ya cerrados no se tocan.</p><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveTransferNew">Pedir la transferencia</button>`);$('#saveTransferNew').onclick=async()=>{const reason=$('#tnReason').value.trim();if(!reason){$('#formError').textContent='Escribí el motivo: es lo que RRHH va a usar para hablar con el responsable nuevo.';return}try{await run(sb.rpc('request_transfer',{p_person_id:id,p_suggested:$('#tnResp').value,p_reason:reason}));$('#modal').close();await loadData();toast('Pedido enviado a RRHH.')}catch(e){$('#formError').textContent=e.message}}}
function cancelTransfer(id){const t=state.transfers.find(x=>x.id===id);if(!t)return;modal('Cancelar el pedido',`<p>Se cancela el pedido de transferencia de <b>${esc(person(t.person_id)?.name||t.person_id)}</b>: queda a tu cargo y podés volver a pedirla cuando haga falta.</p>`,`<button class="btn" data-close>Volver</button><button class="btn danger" id="doCancelTransfer">Cancelar el pedido</button>`);$('#doCancelTransfer').onclick=async()=>{try{await run(sb.rpc('cancel_transfer',{p_id:id}));$('#modal').close();await loadData();toast('Pedido cancelado.')}catch(e){toast(e.message,true)}}}

// Cierre: el que tiene gente a cargo valida siempre; de cada centro usado alcanza con que valide uno de sus responsables.
function closePending(){const pend=new Set();activePeople().forEach(p=>{const o=owner(p);if(o&&responsible(o)?.active!==false&&!validated(o))pend.add(o)});return[...pend].map(responsible).filter(Boolean).sort((a,b)=>a.name.localeCompare(b.name,'es'))}
// RRHH tilda acá a todos los responsables del centro. Agregar no afecta nada; sacar uno vuelve a pedir lo confirmado en los meses abiertos.
function openCenterResponsibles(id){const c=center(id);if(!c)return;const sel=new Set(centerResps(id)),live=liveResponsibles();modal(`Responsables de ${c.name}`,`<p class="small">${esc(c.code)} · ${esc(c.unit)}</p><p>Tildá a todos los que tienen que poder elegir este centro al asignar y confirmar lo que el centro recibe. <b>Alcanza con que confirme uno</b>.</p><div class="checklist">${live.map(r=>`<label class="checkrow"><input type="checkbox" value="${r.id}" ${sel.has(r.id)?'checked':''}><span>${esc(r.name)}</span></label>`).join('')||'<div class="empty">No hay responsables activos.</div>'}</div><div class="notice warn"><b>Si saco un responsable</b>, lo que este centro ya tenía confirmado en los meses abiertos se vuelve a pedir y se reinician las validaciones de los responsables involucrados. Agregar no afecta nada.</div><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveCenterResp">Guardar</button>`);$('#saveCenterResp').onclick=async()=>{const ids=[...document.querySelectorAll('#modal .checkrow input:checked')].map(x=>x.value);try{await run(sb.rpc('set_center_responsibles',{p_center_id:id,p_responsibles:ids}));$('#modal').close();await loadData();toast(ids.length?'Responsables del centro actualizados.':'El centro quedó sin responsables.')}catch(e){$('#formError').textContent=e.message}}}
function centersView(){const active=activeCenters(),inactive=state.centers.filter(c=>!c.active),manage=canManagePeople();return head('Centros','El catálogo se importa en forma autenticada y queda almacenado únicamente en Supabase.',manage?'<button class="btn" id="newCenter">＋ Centro</button><button class="btn primary" id="importCenters">Importar catálogo</button>':'')+`<section class="panel"><div class="panelhead"><div><h2>${active.length} centros vigentes</h2><p>Un centro puede tener más de un responsable: cualquiera de ellos confirma lo que recibe.</p></div></div><div class="tablewrap"><table><thead><tr><th>Código</th><th>Unidad</th><th>Centro</th><th>Tipo</th><th>Responsables</th>${manage?'<th></th>':''}</tr></thead><tbody>${active.map(c=>`<tr><td class="${c.provisional?'provisional':''}">${esc(c.code)}${c.provisional?' · pendiente':''}</td><td>${esc(c.unit)}</td><td><b>${esc(c.name)}</b></td><td>${badge(c.type,c.type==='Beneficio'?'ok':'')}</td><td>${manage?`<button class="btn link" data-center-resp="${esc(c.id)}">${esc(centerRespNames(c.id).join(', ')||'Sin responsable')}</button>`:esc(centerRespNames(c.id).join(', ')||'—')}</td>${manage?`<td><button class="btn danger" data-center-off="${esc(c.id)}">Dar de baja</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${manage?6:5}" class="empty">Todavía no se importó el catálogo de centros.</td></tr>`}</tbody></table></div></section>${inactive.length?`<section class="panel"><div class="panelhead"><div><h2>${inactive.length} ${inactive.length===1?'centro dado':'centros dados'} de baja</h2><p>No se pueden elegir en nuevas asignaciones; los meses anteriores los conservan.</p></div></div><div class="tablewrap"><table><thead><tr><th>Código</th><th>Unidad</th><th>Centro</th><th>Tipo</th>${manage?'<th></th>':''}</tr></thead><tbody>${inactive.map(c=>`<tr><td class="muted">${esc(c.code)}</td><td class="muted">${esc(c.unit)}</td><td class="muted">${esc(c.name)}</td><td>${badge(c.type)}</td>${manage?`<td><button class="btn" data-center-on="${esc(c.id)}">Reactivar</button></td>`:''}</tr>`).join('')}</tbody></table></div></section>`:''}`}

function usersView(){const live=liveResponsibles(),off=state.responsibles.filter(r=>r.active===false);return head('Usuarios y perfiles','Cada usuario ingresa con su correo y contraseña; su perfil determina lo que puede ver y hacer.',`<button class="btn" id="newResponsible">＋ Responsable</button><button class="btn primary" id="newUser">＋ Usuario</button>`)+`<div class="notice"><b>El correo es la identidad de acceso y no se puede cambiar.</b> El nombre sí: se edita desde acá y se actualiza en toda la aplicación. Si alguien cambia de correo, hay que habilitar el nuevo y bloquear el anterior.</div><section class="panel"><div class="panelhead"><div><h2>Accesos habilitados</h2><p>Bloquear un acceso no borra nada: la persona deja de poder entrar y se puede habilitar de nuevo cuando haga falta.</p></div></div><div class="tablewrap"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Perfil</th><th>Estado</th><th>Contraseña</th><th>Acciones</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><b class="${u.active?'':'muted'}">${esc(u.display_name)}</b></td><td class="${u.active?'':'muted'}">${esc(u.email)}</td><td>${badge(roleName(u.role))}</td><td>${u.active?badge('Activo','ok'):badge('Bloqueado','bad')}</td><td>${u.password_set_at?badge(u.must_change_password?'Inicial':'Asignada','ok'):badge('Pendiente','pending')} ${canSetPassword(u)?`<button class="btn link" data-password="${esc(u.email)}">${u.password_set_at?'Restablecer':'Asignar'}</button>`:''}</td><td><div class="actions">${canSetPassword(u)?`<button class="btn" data-user-edit="${esc(u.email)}">Editar</button>${u.email===me.email?badge('Sos vos'):u.active?`<button class="btn danger" data-user-off="${esc(u.email)}">Bloquear</button>`:`<button class="btn" data-user-on="${esc(u.email)}">Habilitar</button>`}`:''}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hay usuarios visibles.</td></tr>'}</tbody></table></div></section>`+respTable(`Maestro de responsables`,live,'Son los que se pueden elegir como responsable principal de una persona y como responsable de un centro. El botón Eliminar aparece sólo mientras el responsable no haya quedado en el historial de nadie; después de eso, el camino es darlo de baja.',true)+(off.length?respTable(`${off.length} ${off.length===1?'responsable dado':'responsables dados'} de baja`,off,'No se ofrecen en la nómina ni en los centros y no pueden iniciar sesión; los meses cerrados conservan su nombre y sus validaciones.',false):'')}
// Maestro de responsables: una tabla para los vigentes y otra para los dados de baja.
function respTable(title,rows,lead,active){return`<section class="panel"><div class="panelhead"><div><h2>${esc(title)}</h2><p>${esc(lead)}</p></div></div><div class="tablewrap"><table><thead><tr><th>Responsable</th><th>Correo</th><th>Colaboradores a cargo</th><th>Centros</th><th>Acciones</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b class="${active?'':'muted'}">${esc(r.name)}</b></td><td class="${active?'':'muted'}">${esc(r.email)}</td><td>${state.people.filter(p=>p.responsible_id===r.id).length}</td><td>${activeCenters().filter(c=>ownsCenter(c.id,r.id)).length}</td><td><div class="actions"><button class="btn" data-resp-edit="${esc(r.id)}">Editar nombre</button>${active?`<button class="btn danger" data-resp-off="${esc(r.id)}">Dar de baja</button>`:`<button class="btn" data-resp-on="${esc(r.id)}">Reactivar</button>`}${respDeletable(r.id)?`<button class="btn danger" data-resp-del="${esc(r.id)}">Eliminar</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="5" class="empty">${active?'Todavía no hay responsables cargados.':'Sin responsables dados de baja.'}</td></tr>`}</tbody></table></div></section>`}
const roleName=r=>({rrhh:'RRHH',responsable:'Responsable',administrador:'Administrador'})[r]||r;

function validationView(){
  const ids=new Set(activePeople().map(owner));activePeople().forEach(p=>allocation(p.id).forEach(a=>centerResps(a.center_id).forEach(x=>ids.add(x))));const reps=[...ids].map(responsible).filter(Boolean),pending=closePending();
  if(me.role==='responsable'){const rid=me.responsible_id,ready=responsibleReady(rid),empty=!myPrimary().length&&!receivedShared().length,done=validated(rid);return head('Validación mensual',`Confirmación de ${periodLabel()}.`)+closedNotice()+`<section class="panel"><div class="panelbody"><div class="summary"><div><h2>${done?'Período validado':empty?'Nada para validar':'Revisión pendiente'}</h2><p>${empty?'No tenés personas ni dedicaciones recibidas en este mes.':ready?(done?'Todas las asignaciones están completas.':'Todo está completo: sólo falta que valides el mes.'):'Antes de validar, resolvé lo siguiente:'}</p></div>${done?badge('Validado','ok'):hrValidated()?badge('Mes cerrado','pending'):empty?'':`<button class="btn primary" id="validateResponsible" ${ready?'':'disabled'}>Validar todo el mes</button>`}</div>${ready||empty?'':pendingDetail(rid,true)}</div></section>`}
  return head('Cierre mensual',`Seguimiento por excepción de ${periodLabel()}.`)+`<div class="cards"><div class="card"><span>Personas</span><strong>${activePeople().length}</strong></div><div class="card"><span>Asignación incompleta</span><strong>${activePeople().filter(p=>!complete(p.id)).length}</strong></div><div class="card"><span>Dedicaciones sin confirmar</span><strong>${activePeople().reduce((s,p)=>s+missingShared(p.id).length,0)}</strong></div><div class="card"><span>Responsables validados</span><strong>${reps.filter(r=>validated(r.id)).length}/${reps.length}</strong></div></div><section class="panel"><div class="panelhead"><div><h2>Estado por responsable</h2><p>Sólo requieren intervención los casos marcados.</p></div>${hrValidated()?`${badge('Mes cerrado','ok')}${canManagePeople()?' <button class="btn" id="reopenMonth">Reabrir mes</button>':''}`:canManagePeople()?`<button class="btn primary" id="validateHr" ${!pending.length&&reps.length?'':`disabled title="${esc(pending.length?'Falta que validen: '+pending.map(r=>r.name).join(', '):'Todavía no hay nada para cerrar en este mes.')}"`}>Validar nómina y cerrar mes</button>`:badge('Mes abierto','pending')}</div>${reps.sort((a,b)=>(validated(a.id)&&responsibleReady(a.id))-(validated(b.id)&&responsibleReady(b.id))||a.name.localeCompare(b.name)).map(r=>`<div class="listrow"><div class="grow"><b>${esc(r.name)}</b><p>${activePeople().filter(p=>owner(p)===r.id).length} colaboradores a cargo</p>${pendingDetail(r.id)}</div><div class="statusline">${responsibleReady(r.id)?badge('Sin pendientes','ok'):badge('Con pendientes','bad')}${validated(r.id)?badge('Validado','ok'):pending.some(x=>x.id===r.id)?badge('Falta click','pending'):badge('No hace falta','')}</div></div>`).join('')||'<div class="empty">Sin responsables para el período.</div>'}</section>`
}

function exportProblems(){const out=[];const people=activePeople();if(!people.length)out.push('No hay personas vigentes.');const incomplete=people.filter(p=>!complete(p.id));if(incomplete.length)out.push(`${incomplete.length} personas no suman 100%.`);const pending=closePending();if(pending.length)out.push(`${pending.length===1?'Un responsable todavía no validó':pending.length+' responsables todavía no validaron'}: ${pending.map(r=>r.name).join(', ')}.`);if(!hrValidated())out.push('RRHH todavía no validó la nómina ni cerró el mes.');if(people.flatMap(p=>allocation(p.id)).some(a=>center(a.center_id)?.provisional))out.push('Hay centros con código provisional.');return out}
function exportView(){const problems=exportProblems();return head('Exportar asignaciones',`Salida del período ${periodLabel()}.`)+`<section class="panel"><div class="exportbox">${problems.length?`<div class="notice danger"><b>La exportación está bloqueada.</b><ul>${problems.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'<div class="notice"><b>Todos los controles están completos.</b><br>El archivo está listo para el modelo de costos.</div>'}<button class="btn primary" id="downloadOutput" ${problems.length?'disabled':''}>Descargar Excel</button></div></section>`}
function historyView(){return head('Historial','Trazabilidad de cambios realizados en la aplicación.')+`<section class="panel"><div class="panelhead"><h2>Actividad reciente</h2></div>${state.events.map(e=>`<div class="listrow"><div><span class="small">${esc(fmtDate(e.created_at))} · ${esc(e.actor_email)}</span><p style="color:var(--ink)">${esc(e.description)}</p></div></div>`).join('')||'<div class="empty">Todavía no hay actividad.</div>'}</section>`}

