  $('#pickAll')&&($('#pickAll').onchange=e=>{const ids=rosterList().map(p=>p.id);ids.forEach(i=>e.target.checked?rosterPicked.add(i):rosterPicked.delete(i));document.querySelectorAll('[data-pick]').forEach(c=>{c.checked=rosterPicked.has(c.dataset.pick)});updateRosterPicks()});
