  $('#validateResponsible')&&($('#validateResponsible').onclick=validateResponsible);$('#filterResponsible')&&($('#filterResponsible').onchange=e=>{assignFilter.responsible=e.target.value;render()});$('#filterPending')&&($('#filterPending').onchange=e=>{assignFilter.pending=!!e.target.value;render()});$('#validateHr')&&($('#validateHr').onclick=validateHr);$('#reopenMonth')&&($('#reopenMonth').onclick=reopenMonth);$('#downloadOutput')&&($('#downloadOutput').onclick=downloadOutput);
