function openNewHire(){
  if(!liveResponsibles().length){toast('Primero cargá al menos un responsable.',true);return}
  modal('Registrar nuevo ingreso',`<div class="split"><label class="field">Legajo<input id="hireId"></label><label class="field">Fecha de alta<input id="hireDate" type="date" value="${monthDate()}"></label></div><label class="field">Apellido y nombre<input id="hireName"></label><label class="field">Responsable principal<select id="hireResp">${liveResponsibles().map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><div id="hireInfo"></div><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveHire">Registrar alta</button>`);
  const dmy=d=>d.split('-').reverse().join('/');let autoName='';$('#hireId').oninput=()=>{const prev=state.people.find(x=>norm(x.id)===norm($('#hireId').value));$('#hireInfo').innerHTML=!prev?'':prev.end_date?`<div class="notice">El legajo <b>${esc(prev.id)}</b> es de <b>${esc(prev.name)}</b>, con baja el ${dmy(prev.end_date)}. Se va a registrar como <b>reingreso</b> de la misma persona: la fecha de alta pasa a ser la nueva y necesitará una asignación desde ese mes.</div>`:`<div class="notice danger">El legajo <b>${esc(prev.id)}</b> ya corresponde a <b>${esc(prev.name)}</b>, que está activa.</div>`;const nameEl=$('#hireName');if(!nameEl.value||nameEl.value===autoName){autoName=prev?.name||'';nameEl.value=autoName}};
  $('#saveHire').onclick=async()=>{const row={id:$('#hireId').value.trim(),name:$('#hireName').value.trim(),start_date:$('#hireDate').value,responsible_id:$('#hireResp').value};if(!row.id||!row.name||!row.start_date){$('#formError').textContent='Completá todos los datos.';return}try{const kind=await run(sb.rpc('register_hire',{p_id:row.id,p_name:row.name,p_start:row.start_date,p_responsible_id:row.responsible_id}));$('#modal').close();await loadData();toast(kind==='reingreso'?'Reingreso registrado. Quedó pendiente la asignación desde el nuevo ingreso.':'Alta registrada. Quedó pendiente la asignación.')}catch(e){$('#formError').textContent=e.message}}
}
function openEnd(id){const p=person(id);modal('Registrar o modificar baja',`<p><b>${esc(p.name)}</b> · ${esc(p.id)}</p><label class="field">Último día activo<input id="endDate" type="date" min="${p.start_date}" value="${p.end_date||monthEnd()}"></label><label class="field">Motivo u observación<input id="endReason"></label><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveEnd">Guardar</button>`);$('#saveEnd').onclick=async()=>{const date=$('#endDate').value;if(!date||date<p.start_date){$('#formError').textContent='Revisá la fecha de baja.';return}try{const rows=await run(sb.from('people').update({end_date:date,updated_at:new Date().toISOString()}).eq('id',id).select('id'));if(!rows?.length)throw new Error('No se pudo guardar la baja.');await audit('termination',`Baja de ${p.name} al ${date}${$('#endReason').value.trim()?': '+$('#endReason').value.trim():''}`);$('#modal').close();await loadData();toast('Baja registrada; el historial se conserva.')}catch(e){$('#formError').textContent=e.message}}}
// Asigna el mismo responsable a todas las personas seleccionadas, una por una, con el mismo historial que el cambio individual.
function openBulkOwner(){
  const ids=[...rosterPicked].filter(id=>person(id));if(!ids.length){toast('No hay personas seleccionadas.',true);return}
  if(!liveResponsibles().length){toast('Primero cargá al menos un responsable.',true);return}
  modal('Asignar responsable a varias personas',`<p><b>${ids.length} persona${ids.length===1?'':'s'} seleccionada${ids.length===1?'':'s'}.</b></p><div class="split"><label class="field">Responsable<select id="bulkResp">${liveResponsibles().map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><label class="field">Desde el mes<input id="bulkDate" type="month" value="${period}"></label></div><label class="field">Motivo<input id="bulkReason" placeholder="Ej.: carga inicial de responsables"></label><p class="small">Los meses anteriores conservan el responsable que tenían. Las personas que ya tienen ese responsable se saltean.</p><div id="bulkProgress" class="small"></div><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveBulk">Asignar</button>`);
  $('#saveBulk').onclick=async()=>{
    const rid=$('#bulkResp').value,month=$('#bulkDate').value;if(!/^\d{4}-\d{2}$/.test(month)){$('#formError').textContent='Indicá desde qué mes.';return}
    $('#saveBulk').disabled=true;let ok=0,skip=0,fail=0,err='';
    for(const id of ids){const p=person(id);
      if(!p||owner(p)===rid){skip++}
      else{try{await run(sb.rpc('change_responsible',{p_person_id:id,p_from:month+'-01',p_responsible_id:rid,p_reason:$('#bulkReason').value.trim()||null}));ok++}catch(e){fail++;err=err||e.message}}
      $('#bulkProgress')&&($('#bulkProgress').textContent=`Procesadas ${ok+skip+fail} de ${ids.length}…`)}
    if(ok)rosterPicked.clear();
    $('#modal').close();await loadData();
    toast(fail?`${ok} asignadas y ${fail} con error. ${err}`:`${ok} persona${ok===1?'':'s'} asignada${ok===1?'':'s'}${skip?` · ${skip} ya tenían ese responsable`:''}.`,!!fail)}
}
function openOwner(id){const p=person(id),hist=state.history.filter(h=>h.person_id===id&&h.valid_from>=p.start_date);modal('Cambiar responsable principal',`<p><b>${esc(p.name)}</b> · ${esc(p.id)}</p><div class="split"><label class="field">Nuevo responsable<select id="ownerResp">${liveResponsibles().map(r=>`<option value="${r.id}" ${r.id===owner(p)?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label class="field">Desde el mes<input id="ownerDate" type="month" min="${p.start_date.slice(0,7)}" ${p.end_date?`max="${p.end_date.slice(0,7)}"`:''} value="${period}"></label></div><label class="field">Motivo<input id="ownerReason" placeholder="Ej.: transferencia de sector"></label><p class="small">Los meses anteriores conservan el responsable que tenían.${hist.length>1?` Historial: ${hist.map(h=>`desde ${esc(monthLabel(h.valid_from))}, ${esc(responsible(h.responsible_id)?.name||'—')}`).join(' · ')}.`:''}</p><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveOwner">Guardar</button>`);$('#saveOwner').onclick=async()=>{const rid=$('#ownerResp').value,month=$('#ownerDate').value;if(!/^\d{4}-\d{2}$/.test(month)){$('#formError').textContent='Indicá desde qué mes.';return}try{await run(sb.rpc('change_responsible',{p_person_id:id,p_from:month+'-01',p_responsible_id:rid,p_reason:$('#ownerReason').value.trim()||null}));$('#modal').close();await loadData();toast(`Responsable actualizado desde ${monthLabel(month)}.`)}catch(e){$('#formError').textContent=e.message}}}

function openAssignment(id){
  const p=person(id),rid=owner(p),existing=allocation(id),ownCount=state.centers.filter(c=>c.active&&ownsCenter(c.id,rid)).length;let showAll=!ownCount;const rows=existing.length?existing.map(x=>({center_id:x.center_id,pct:Number(x.pct)})):[{center_id:'',pct:100}];
  modal(`Asignar a ${p.name}`,`<label class="field">Vigente desde el mes<input id="assignmentDate" type="month" value="${period}" min="${p.start_date.slice(0,7)}" ${p.end_date?`max="${p.end_date.slice(0,7)}"`:''}></label><div id="allocationRows"></div>${ownCount?`<label class="showall"><input type="checkbox" id="showAllCenters"><span>Mostrar también centros de otros responsables<small>Esa parte quedará pendiente hasta que el responsable del centro la confirme.</small></span></label>`:''}<button class="btn" id="addLine">＋ Agregar centro</button><div id="allocationTotal"></div><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveAssignment">Guardar asignación</button>`);
  const paintTotal=()=>{const sum=rows.reduce((s,r)=>s+Number(r.pct||0),0);$('#allocationTotal').innerHTML=`<div class="total ${Math.abs(sum-100)<.001?'ok':'bad'}"><span>Total</span><b>${sum.toFixed(2)}%</b></div>`};
  const paint=()=>{$('#allocationRows').innerHTML=rows.map((r,i)=>`<div class="allocrow"><select data-line-center="${i}">${centerOptions(r.center_id,rid,showAll)}</select><input data-line-pct="${i}" type="number" min="0.01" max="100" step="0.01" value="${r.pct||''}"><button class="btn danger" data-remove-line="${i}">×</button></div>`).join('');paintTotal();document.querySelectorAll('[data-line-center]').forEach(s=>s.onchange=()=>{rows[+s.dataset.lineCenter].center_id=s.value});document.querySelectorAll('[data-line-pct]').forEach(n=>n.oninput=()=>{rows[+n.dataset.linePct].pct=Number(n.value);paintTotal()});document.querySelectorAll('[data-remove-line]').forEach(b=>b.onclick=()=>{rows.splice(+b.dataset.removeLine,1);paint()})};
  paint();$('#showAllCenters')&&($('#showAllCenters').onchange=e=>{showAll=e.target.checked;paint()});$('#addLine').onclick=()=>{rows.push({center_id:'',pct:0});paint()};$('#saveAssignment').onclick=async()=>{const month=$('#assignmentDate').value;if(!/^\d{4}-\d{2}$/.test(month)){$('#formError').textContent='Indicá desde qué mes rige la asignación.';return}if(rows.some(r=>!r.center_id&&Number(r.pct)>0)){$('#formError').textContent='Elegí un centro en cada fila con porcentaje.';return}const clean=rows.filter(r=>r.center_id&&r.pct>0),sum=clean.reduce((s,r)=>s+Number(r.pct),0);if(!clean.length||Math.abs(sum-100)>.001){$('#formError').textContent='La distribución debe sumar exactamente 100%.';return}if(new Set(clean.map(r=>r.center_id)).size!==clean.length){$('#formError').textContent='No repitas centros.';return}const off=clean.map(r=>center(r.center_id)).find(c=>c&&!c.active);if(off){$('#formError').textContent=`${off.name} está dado de baja: reemplazalo por otro centro.`;return}const[y,m]=month.split('-').map(Number),prev=currentVersion(id,new Date(Date.UTC(y,m,0)).toISOString().slice(0,10))?.id;try{const saved=await run(sb.rpc('save_assignment',{p_person_id:id,p_valid_from:month+'-01',p_lines:clean}));$('#modal').close();await loadData();toast(saved===prev?'No hubo cambios: la asignación ya era esa.':`Asignación guardada desde ${monthLabel(month)}. Si cambió un porcentaje en un centro de otro responsable, deberá confirmarlo de nuevo.`)}catch(e){$('#formError').textContent=e.message}}
}
function centerOptions(sel,rid,all){const opt=c=>`<option value="${c.id}" ${sel===c.id?'selected':''}>${esc(`${c.code} · ${c.name} · ${c.unit}${c.active?'':' · DADO DE BAJA'}`)}</option>`,avail=state.centers.filter(c=>c.active||c.id===sel),mine=avail.filter(c=>ownsCenter(c.id,rid)),rest=avail.filter(c=>!mine.includes(c)&&(all||c.id===sel)),groups=new Map();rest.forEach(c=>{const k=centerRespNames(c.id).join(' o ');groups.has(k)||groups.set(k,[]);groups.get(k).push(c)});const own=me?.role==='responsable'&&me.responsible_id===rid?'Mis centros':`Centros de ${responsible(rid)?.name||'su responsable'}`,other=[...groups].map(([k,cs])=>({label:k?`De ${k} · requiere su confirmación`:'Sin responsable asignado',cs})).sort((a,b)=>a.label.localeCompare(b.label,'es'));return`<option value="">Elegir centro</option>${mine.length?`<optgroup label="${esc(own)}">${mine.map(opt).join('')}</optgroup>`:''}${other.map(g=>`<optgroup label="${esc(g.label)}">${g.cs.map(opt).join('')}</optgroup>`).join('')}`}
function openDetail(id){modal(`Asignación de ${person(id).name}`,allocationHtml(id),`<button class="btn" data-close>Cerrar</button>`)}
async function confirmShared(key){const[personId,centerId]=key.split('|');try{await run(sb.rpc('confirm_shared',{p_period:monthDate(),p_person_id:personId,p_center_id:centerId}));await loadData();toast('Dedicación confirmada.')}catch(e){toast(e.message,true);await loadData().catch(()=>{})}}
function openNewCenter(){const units=[...new Set(state.centers.map(c=>c.unit))].sort();modal('Nuevo centro',`<label class="field">Código<input id="centerCode"></label><label class="field">Unidad<input id="centerUnit" list="centerUnits"><datalist id="centerUnits">${units.map(u=>`<option value="${esc(u)}">`).join('')}</datalist></label><label class="field">Centro<input id="centerName"></label><label class="field">Tipo<select id="centerType"><option value="">Elegir</option><option>Costo</option><option>Beneficio</option></select></label><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveCenter">Guardar</button>`);$('#saveCenter').onclick=async()=>{const code=$('#centerCode').value.trim(),unit=$('#centerUnit').value.trim(),name=$('#centerName').value.trim(),type=$('#centerType').value;if(!code||!unit||!name||!type){$('#formError').textContent='Completá código, unidad, centro y tipo.';return}const dup=state.centers.find(c=>norm(c.code)===norm(code));if(dup){$('#formError').textContent=dup.active?`Ya existe el centro ${dup.name} con ese código.`:`Ese código es de ${dup.name}, que está dado de baja: usá Reactivar.`;return}try{await run(sb.from('centers').insert({id:code,code,unit,name,type,provisional:norm(code)==='prueba',active:true,sort_order:Math.max(0,...state.centers.map(c=>c.sort_order||0))+1}));await audit('center_create',`Alta de centro ${code} · ${name}`);$('#modal').close();await loadData();toast('Centro creado.')}catch(e){$('#formError').textContent=e.message}}}
function openCenterOff(id){const c=center(id),users=activePeople().filter(p=>allocation(p.id).some(a=>a.center_id===id));modal('Dar de baja centro',`<p><b>${esc(c.code)} · ${esc(c.name)}</b> · ${esc(c.unit)}</p><p>Desde ahora no se va a poder elegir en nuevas asignaciones. Las asignaciones y exportaciones de meses anteriores lo conservan.</p>${users.length?`<div class="notice danger"><b>${users.length} ${users.length===1?'persona lo tiene':'personas lo tienen'} en su asignación vigente:</b> ${users.map(p=>esc(p.name)).join(', ')}.<br>Van a quedar marcadas para reasignar.</div>`:''}`,`<button class="btn" data-close>Cancelar</button><button class="btn danger" id="confirmCenterOff">Dar de baja</button>`);$('#confirmCenterOff').onclick=async()=>{$('#modal').close();await setCenterActive(id,false)}}
async function setCenterActive(id,active){const c=center(id);try{await run(sb.from('centers').update({active}).eq('id',id));await audit(active?'center_reactivate':'center_deactivate',`${active?'Reactivación':'Baja'} de centro ${c.code} · ${c.name}`);await loadData();toast(active?'Centro reactivado.':'Centro dado de baja.')}catch(e){toast(e.message,true)}}
function confirmAction(title,body,label,action){modal(title,body,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="confirmAction">${esc(label)}</button>`);$('#confirmAction').onclick=async()=>{$('#modal').close();try{await action()}catch(e){toast(e.message,true)}}}
function validateResponsible(){const mes=periodLabel();confirmAction('Validar el mes',`<p>Vas a validar <b>${esc(mes)}</b>: confirmás que las asignaciones de tu personal y las dedicaciones que recibiste son correctas.</p><p class="small">Si después se modifica algo que te involucre, el mes vuelve a quedar pendiente de tu validación.</p>`,'Validar mes',async()=>{await run(sb.rpc('validate_responsible_month',{p_period:monthDate()}));await loadData();toast('Mes validado.')})}
function validateHr(){const mes=periodLabel();confirmAction('Validar nómina y cerrar el mes',`<p>Vas a cerrar <b>${esc(mes)}</b>. Desde ese momento nadie puede modificar altas, bajas, responsables, asignaciones ni confirmaciones que alcancen este mes.</p><p class="small">Si hace falta corregir algo, se puede reabrir desde esta misma pantalla.</p>`,'Cerrar mes',async()=>{await run(sb.rpc('close_month',{p_period:monthDate()}));await loadData();toast('Nómina validada: el mes quedó cerrado.')})}
function reopenMonth(){const mes=periodLabel();confirmAction('Reabrir el mes',`<p>Vas a reabrir <b>${esc(mes)}</b> para permitir correcciones. Las validaciones de los responsables se conservan, salvo las que se vean afectadas por los cambios.</p>`,'Reabrir mes',async()=>{await run(sb.rpc('reopen_month',{p_period:monthDate()}));await loadData();toast('Mes reabierto.')})}

function openClearTest(){modal('Vaciar datos de prueba','<div class="notice danger"><b>Se eliminarán personas, responsables, asignaciones y validaciones.</b><br>El catálogo de centros, el administrador y los usuarios de RRHH se conservan. Usá esta opción sólo antes de la carga real.</div>',`<button class="btn" data-close>Cancelar</button><button class="btn danger" id="confirmClearTest">Vaciar datos</button>`);$('#confirmClearTest').onclick=async()=>{try{await run(sb.rpc('clear_operational_data'));$('#modal').close();await loadData();toast('Datos operativos eliminados. Ya podés importar la nómina real.')}catch(e){toast(e.message,true)}}}

function openNewResponsible(){
  modal('Nuevo responsable',`<label class="field">Nombre y apellido<input id="respName"></label><label class="field">Correo<input id="respEmail" type="email"></label>${initialPasswordField()}<div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveResponsible">Guardar</button>`);bindInitialPassword();
  $('#saveResponsible').onclick=async()=>{const name=$('#respName').value.trim(),email=$('#respEmail').value.trim().toLowerCase();if(!name||!email){$('#formError').textContent='Completá nombre y correo.';return}const pwd=readInitialPassword();if(!pwd)return;try{const data=await run(sb.from('responsibles').insert({name,email}).select().single());await run(sb.from('app_users').upsert({email,display_name:name,role:'responsable',responsible_id:data.id,active:true}));await run(sb.rpc('set_user_password',{target_email:email,new_password:pwd}));await audit('access',`Alta del responsable ${name}`);$('#modal').close();await loadData();toast('Responsable y acceso creados.')}catch(e){$('#formError').textContent=e.message}}
}
function openNewUser(){
  modal('Habilitar usuario',`<label class="field">Nombre<input id="userName"></label><label class="field">Correo<input id="userEmail" type="email"></label><label class="field">Perfil<select id="userRole"><option value="rrhh">RRHH</option>${me.role==='administrador'?'<option value="administrador">Administrador de costos</option>':''}</select></label>${initialPasswordField()}<div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveUser">Guardar</button>`);bindInitialPassword();
  $('#saveUser').onclick=async()=>{const row={display_name:$('#userName').value.trim(),email:$('#userEmail').value.trim().toLowerCase(),role:$('#userRole').value,active:true};if(!row.display_name||!row.email){$('#formError').textContent='Completá nombre y correo.';return}const pwd=readInitialPassword();if(!pwd)return;try{await run(sb.from('app_users').upsert(row));await run(sb.rpc('set_user_password',{target_email:row.email,new_password:pwd}));await audit('access',`Acceso ${row.role} habilitado para ${row.email}`);$('#modal').close();await loadData();toast('Usuario habilitado.')}catch(e){$('#formError').textContent=e.message}}
}

// Edición del nombre y bloqueo o habilitación de un acceso. El correo no se toca: es la identidad en Supabase Auth.
function openEditUser(email){const u=state.users.find(x=>x.email===email);if(!u||!canSetPassword(u))return;const r=u.responsible_id?responsible(u.responsible_id):null;const isSelf=email===me.email,canChangeRole=me.role==='administrador'&&!isSelf;
  const canBeResp=!!u.responsible_id;const roleOpts=canChangeRole?`<label class="field">Perfil<select id="editUserRole">${canBeResp?`<option value="responsable" ${u.role==='responsable'?'selected':''}>Responsable</option>`:''}<option value="rrhh" ${u.role==='rrhh'?'selected':''}>RRHH</option><option value="administrador" ${u.role==='administrador'?'selected':''}>Administrador de costos</option></select>${canBeResp?'':'<p class="small">Para darle el perfil Responsable, creálo con ＋ Responsable usando este mismo correo: eso le genera el registro en el maestro y le cambia el perfil.</p>'}</label>`:`<label class="field">Perfil<input value="${esc(roleName(u.role))}" disabled></label>`;
  modal('Editar usuario',`<p class="small">${esc(u.email)}</p><label class="field">Nombre<input id="editUserName" value="${esc(u.display_name)}"></label>${roleOpts}${r?`<p class="small">Se actualiza también en el maestro de responsables, donde figura como <b>${esc(r.name)}</b>.</p>`:''}<p class="small">El correo no se puede cambiar porque es con el que la persona inicia sesión. Si cambió de correo, habilitá el nuevo y bloqueá este.</p><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveUserName">Guardar</button>`);
  $('#saveUserName').onclick=async()=>{const name=$('#editUserName').value.trim();if(!name){$('#formError').textContent='Completá el nombre.';return}const newRole=$('#editUserRole')?$('#editUserRole').value:u.role;const nameChanged=name!==u.display_name,roleChanged=newRole!==u.role;if(roleChanged&&u.role==='responsable'){const pCount=state.people.filter(p=>p.responsible_id===u.responsible_id).length;if(pCount){$('#formError').textContent=`Tiene ${pCount} persona${pCount===1?'':'s'} a cargo. Reasignalas primero desde Nómina.`;return}}if(!nameChanged&&!roleChanged){$('#modal').close();return}try{const upd={};if(nameChanged)upd.display_name=name;if(roleChanged)upd.role=newRole;await run(sb.from('app_users').update(upd).eq('email',email));if(nameChanged&&u.responsible_id)await run(sb.from('responsibles').update({name}).eq('id',u.responsible_id));const parts=[];if(nameChanged)parts.push(`nombre: ${u.display_name} → ${name}`);if(roleChanged)parts.push(`perfil: ${roleName(u.role)} → ${roleName(newRole)}`);await audit('access',`Edición de ${email}: ${parts.join(', ')}`);$('#modal').close();await loadData();toast(parts.length===1&&roleChanged?'Perfil actualizado.':nameChanged&&roleChanged?'Nombre y perfil actualizados.':'Nombre actualizado.')}catch(e){$('#formError').textContent=e.message}}}
function openUserOff(email){const u=state.users.find(x=>x.email===email);if(!u||!canSetPassword(u)||email===me.email)return;const r=u.responsible_id?responsible(u.responsible_id):null;
  if(r&&r.active!==false){modal('Bloquear acceso',`<p><b>${esc(u.display_name)}</b> · ${esc(u.email)}</p><div class="notice danger">Este acceso es de un responsable que sigue vigente. Si lo que querés es sacarlo del circuito, dale de baja en el <b>maestro de responsables</b>: eso bloquea el acceso y además lo saca de la nómina y de los centros.</div><p class="small">Si sólo querés que no pueda entrar por un rato pero siga figurando como responsable, seguí con el bloqueo.</p>`,`<button class="btn" data-close>Cancelar</button><button class="btn danger" id="confirmUserOff">Bloquear sólo el acceso</button>`);$('#confirmUserOff').onclick=async()=>{$('#modal').close();await setUserActive(email,false)};return}
  modal('Bloquear acceso',`<p>Vas a bloquear el acceso de <b>${esc(u.display_name)}</b> · ${esc(u.email)}. No va a poder iniciar sesión hasta que lo habilites de nuevo.</p><p class="small">No se borra nada: el usuario, su contraseña y todo su historial quedan como están.</p>`,`<button class="btn" data-close>Cancelar</button><button class="btn danger" id="confirmUserOff">Bloquear</button>`);$('#confirmUserOff').onclick=async()=>{$('#modal').close();await setUserActive(email,false)}}
async function setUserActive(email,active){const u=state.users.find(x=>x.email===email);if(!u||!canSetPassword(u)||email===me.email)return;try{await run(sb.from('app_users').update({active}).eq('email',email));await audit('access',`${active?'Habilitación':'Bloqueo'} del acceso de ${u.display_name} (${email})`);await loadData();toast(active?'Acceso habilitado.':'Acceso bloqueado.')}catch(e){toast(e.message,true)}}

// Baja de un responsable: sólo si no le quedan personas a cargo, para que nadie quede sin responsable.
function openEditResponsible(id){const r=responsible(id);if(!r)return;
  modal('Editar nombre',`<p class="small">${esc(r.email)}</p><label class="field">Nombre y apellido<input id="editRespName" value="${esc(r.name)}"></label><p class="small">Se actualiza en toda la aplicación, también en los meses ya cerrados. El correo no se puede cambiar porque es con el que inicia sesión.</p><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveRespName">Guardar</button>`);
  $('#saveRespName').onclick=async()=>{const name=$('#editRespName').value.trim();if(!name){$('#formError').textContent='Completá el nombre.';return}if(name===r.name){$('#modal').close();return}try{await run(sb.from('responsibles').update({name}).eq('id',id));await run(sb.from('app_users').update({display_name:name}).eq('email',r.email));await audit('access',`Cambio de nombre del responsable ${r.name} a ${name}`);$('#modal').close();await loadData();toast('Nombre actualizado.')}catch(e){$('#formError').textContent=e.message}}}
function openResponsibleOff(id){const r=responsible(id);if(!r)return;const mine=state.people.filter(p=>p.responsible_id===id),centers=activeCenters().filter(c=>ownsCenter(c.id,id));
  if(mine.length){modal('Primero hay que reasignar su gente',`<p><b>${esc(r.name)}</b> tiene ${mine.length} ${mine.length===1?'persona':'personas'} a cargo.</p><div class="notice danger">Si lo doy de baja ahora, esas personas quedan sin responsable y nadie puede cargar su asignación.<br>Andá a <b>Nómina</b>, filtrá por ${esc(r.name)}, tildá las personas y usá <b>Asignar responsable</b> para pasarlas todas juntas a otro responsable. Después volvés acá.</div><p class="small">${mine.slice(0,25).map(p=>esc(p.name)).join(' · ')}${mine.length>25?` y ${mine.length-25} más.`:''}</p>`,'<button class="btn primary" data-close>Entendido</button>');return}
  modal('Dar de baja responsable',`<p><b>${esc(r.name)}</b> · ${esc(r.email)}</p><p>Deja de ofrecerse en la nómina y en los centros, y no va a poder iniciar sesión. Los meses anteriores conservan su nombre, sus asignaciones y sus validaciones.</p>${centers.length?`<div class="notice danger"><b>Es responsable de ${centers.length} ${centers.length===1?'centro':'centros'}:</b> ${centers.map(c=>esc(c.code+' · '+c.name)).join(' / ')}.<br>Lo van a dejar de tener como responsable. Los que queden sin ninguno no van a pedir confirmación hasta que les asignes uno en <b>Centros</b>.</div>`:''}<p class="small">Se puede reactivar en cualquier momento desde esta misma pantalla.</p>`,`<button class="btn" data-close>Cancelar</button><button class="btn danger" id="confirmRespOff">Dar de baja</button>`);
  $('#confirmRespOff').onclick=async()=>{$('#modal').close();await setResponsibleActive(id,false)}}
async function setResponsibleActive(id,active){const r=responsible(id);if(!r)return;try{if(!active)await run(sb.rpc('remove_responsible_from_centers',{p_responsible_id:id}));await run(sb.from('responsibles').update({active}).eq('id',id));await run(sb.from('app_users').update({active}).eq('email',r.email));await audit('access',`${active?'Reactivación':'Baja'} del responsable ${r.name}`);await loadData();toast(active?'Responsable reactivado: ya se puede elegir y volver a entrar.':'Responsable dado de baja.')}catch(e){toast(e.message,true)}}
// Borrado definitivo: solo si el responsable no dejo rastro. Si alguna vez tuvo gente a cargo, queda historial y la base
// (por clave foranea) rechaza el delete; en ese caso el boton no se ofrece y el camino es darlo de baja.
const respRefs=id=>({people:state.people.filter(p=>p.responsible_id===id).length,history:state.history.filter(h=>h.responsible_id===id).length,validations:state.validations.filter(v=>v.responsible_id===id).length});
function respDeletable(id){const r=responsible(id);if(!r||!canManagePeople()||r.email===me?.email)return false;const n=respRefs(id);return!n.people&&!n.history&&!n.validations}
function openResponsibleDelete(id){const r=responsible(id);if(!respDeletable(id))return;const centers=activeCenters().filter(c=>ownsCenter(c.id,id));
  modal('Eliminar responsable',`<p><b>${esc(r.name)}</b> · ${esc(r.email)}</p><div class="notice danger"><b>Se borra de la base y no se puede deshacer.</b><br>Se puede eliminar porque no tiene ninguna persona a cargo, ninguna fila de historial y ninguna validación mensual: no hay nada que perder. En cuanto un responsable aparece en el historial de alguien, este botón desaparece y sólo queda darlo de baja.</div>${centers.length?`<div class="notice"><b>Es responsable de ${centers.length} ${centers.length===1?'centro':'centros'}:</b> ${centers.map(c=>esc(c.code+' · '+c.name)).join(' / ')}.<br>Lo van a dejar de tener como responsable: revisá en <b>Centros</b> que no quede ninguno sin nadie.</div>`:''}<p class="small">Su usuario de Supabase Auth queda huérfano: no va a poder iniciar sesión, pero para borrarlo del todo hay que eliminarlo a mano en el panel de Supabase, en Authentication → Users.</p><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn danger" id="confirmRespDel">Eliminar definitivamente</button>`);
  $('#confirmRespDel').onclick=async()=>{try{await run(sb.rpc('remove_responsible_from_centers',{p_responsible_id:id}));await run(sb.from('app_users').delete().eq('email',r.email));await run(sb.from('responsibles').delete().eq('id',id));await audit('access',`Eliminación definitiva del responsable ${r.name} (${r.email})`);$('#modal').close();await loadData();toast('Responsable eliminado.')}catch(e){$('#formError').textContent=e.code==='23503'?'La base encontró historial asociado, así que no se puede eliminar. Usá «Dar de baja» en lugar de eliminar.':e.message}}}

function openImport(){
  modal('Importación inicial',`<div class="drop"><strong>Seleccioná la plantilla completa</strong><span>Debe contener las hojas “Nomina” y “Responsables”. Sólo está habilitado cuando la nómina está vacía.</span><label class="btn primary" for="rosterFile">Elegir Excel</label><input id="rosterFile" type="file" accept=".xlsx"></div><div id="importPreview"></div><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="confirmImport" disabled>Importar nómina</button>`);
  let parsed;$('#rosterFile').onchange=async e=>{try{parsed=await parseRosterXlsx(await e.target.files[0].arrayBuffer());$('#importPreview').innerHTML=`<div class="notice" style="margin-top:15px"><b>${parsed.people.length} personas y ${parsed.responsibles.length} responsables.</b></div>`;$('#confirmImport').disabled=false}catch(err){$('#formError').textContent=err.message}};
  $('#confirmImport').onclick=async()=>{try{const respRows=await run(sb.from('responsibles').upsert(parsed.responsibles,{onConflict:'email'}).select());const byName=new Map(respRows.map(r=>[norm(r.name),r]));for(const r of respRows)await run(sb.from('app_users').upsert({email:r.email,display_name:r.name,role:'responsable',responsible_id:r.id,active:true}));const people=parsed.people.map(p=>({...p,responsible_id:byName.get(norm(p.responsible_name))?.id}));if(people.some(p=>!p.responsible_id))throw new Error('Hay responsables de la nómina que no aparecen en la hoja Responsables.');await run(sb.from('people').insert(people.map(({responsible_name,...p})=>p)));for(const p of people)await run(sb.from('responsible_history').insert({person_id:p.id,valid_from:p.start_date,responsible_id:p.responsible_id,created_by:session.user.email}));await audit('initial_import',`Importación inicial: ${people.length} personas`);$('#modal').close();await loadData();toast('Importación inicial completada.')}catch(err){$('#formError').textContent=err.message}}
}

function openImportCenters(){
  modal('Importar centros',`<div class="drop"><strong>Seleccioná el Excel de centros de DMO</strong><span>La hoja debe incluir Código, Unidad, Centro y Tipo. Tipo debe indicar Costo o Beneficio.</span><label class="btn primary" for="centersFile">Elegir Excel</label><input id="centersFile" type="file" accept=".xlsx"></div><div id="centersPreview"></div><div id="formError" class="error"></div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" id="confirmCenters" disabled>Importar centros</button>`);
  let rows;$('#centersFile').onchange=async e=>{try{rows=await parseCentersXlsx(await e.target.files[0].arrayBuffer());$('#centersPreview').innerHTML=`<div class="notice" style="margin-top:15px"><b>${rows.length} centros encontrados.</b><br>Los códigos existentes se actualizarán.</div>`;$('#confirmCenters').disabled=false}catch(err){$('#formError').textContent=err.message}};
  $('#confirmCenters').onclick=async()=>{try{await run(sb.from('centers').upsert(rows,{onConflict:'id'}));await audit('centers_import',`Importación de catálogo: ${rows.length} centros`);$('#modal').close();await loadData();toast('Catálogo de centros actualizado.')}catch(err){$('#formError').textContent=err.message}}
}

async function parseCentersXlsx(buffer){
  const book=await readWorkbook(buffer);for(const sheetRows of book.values()){const hi=sheetRows.findIndex(r=>{const h=r.map(norm);return h.some(x=>['codigo','codigocentro','codigocentrocosto'].includes(x))&&h.some(x=>['centro','nombre','nombrecentro','centrodecostos','centrodecosto'].includes(x))&&h.includes('tipo')});if(hi<0)continue;const h=headerMap(sheetRows[hi]),idx=names=>names.map(n=>h[norm(n)]).find(i=>i!==undefined),codeIdx=idx(['codigo','codigo_centro','codigo_centro_costo']),unitIdx=idx(['unidad','sede']),nameIdx=idx(['centro','nombre','nombre_centro','centro_de_costos','centro_de_costo']),typeIdx=idx(['tipo']);const rows=sheetRows.slice(hi+1).filter(r=>String(r[codeIdx]??'').trim()).map((r,i)=>{const code=String(r[codeIdx]).trim(),rawType=norm(r[typeIdx]),type=rawType.includes('beneficio')?'Beneficio':rawType.includes('costo')?'Costo':'';if(!type)throw new Error(`Tipo inválido en la fila ${hi+i+2}. Debe ser Costo o Beneficio.`);return{id:code,code,unit:String(r[unitIdx]??'').trim()||'Sin unidad',name:String(r[nameIdx]??'').trim(),type,provisional:norm(code)==='prueba',active:true,sort_order:i+1}});if(rows.some(r=>!r.name))throw new Error('Hay centros sin nombre.');if(new Set(rows.map(r=>norm(r.code))).size!==rows.length)throw new Error('Hay códigos de centro repetidos.');return rows}throw new Error('No se encontró una hoja con las columnas Código, Centro y Tipo.')
}

async function parseRosterXlsx(buffer){
  const book=await readWorkbook(buffer),nom=book.get('nomina'),res=book.get('responsables');if(!nom||!res)throw new Error('El archivo debe tener las hojas Nomina y Responsables.');
  const ni=nom.findIndex(r=>r.map(norm).includes('legajo')&&r.map(norm).includes('responsableprincipal')),ri=res.findIndex(r=>r.map(norm).includes('responsableprincipal')&&r.map(norm).includes('correoresponsable'));if(ni<0||ri<0)throw new Error('No se encontraron los encabezados esperados en la plantilla.');
  const rh=headerMap(res[ri]),nh=headerMap(nom[ni]);
  const responsibles=res.slice(ri+1).filter(r=>r.some(Boolean)).map(r=>({name:cell(r,rh,'responsable_principal'),email:cell(r,rh,'correo_responsable').toLowerCase(),active:true}));
  const people=nom.slice(ni+1).filter(r=>r.some(Boolean)).map(r=>({id:cell(r,nh,'legajo'),name:cell(r,nh,'nombre'),responsible_name:cell(r,nh,'responsable_principal'),start_date:excelDate(cell(r,nh,'fecha_alta'))||'2025-01-01',end_date:excelDate(cell(r,nh,'fecha_baja'))||null,active:true}));
  if(responsibles.some(r=>!r.name||!r.email)||people.some(p=>!p.id||!p.name||!p.responsible_name))throw new Error('Hay filas incompletas en la plantilla.');if(new Set(people.map(p=>norm(p.id))).size!==people.length)throw new Error('Hay legajos repetidos.');return{responsibles,people}
}
const headerMap=row=>Object.fromEntries((row||[]).map((v,i)=>[norm(v),i]));
const cell=(row,map,name)=>String(row[map[norm(name)]]??'').trim();
function excelDate(v){if(!v)return'';if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;if(/^\d+(\.\d+)?$/.test(v)){const d=new Date(Date.UTC(1899,11,30)+Number(v)*86400000);return d.toISOString().slice(0,10)}const p=String(v).split('/');if(p.length===3)return`${p[2]}-${p[1].padStart(2,'0')}-${p[0].padStart(2,'0')}`;return''}
async function readWorkbook(buffer){
  const zip=await JSZip.loadAsync(buffer),parser=new DOMParser(),wb=parser.parseFromString(await zip.file('xl/workbook.xml').async('string'),'application/xml'),rels=parser.parseFromString(await zip.file('xl/_rels/workbook.xml.rels').async('string'),'application/xml'),shared=[];
  const sf=zip.file('xl/sharedStrings.xml');if(sf){const sx=parser.parseFromString(await sf.async('string'),'application/xml');[...sx.getElementsByTagName('si')].forEach(si=>shared.push([...si.getElementsByTagName('t')].map(t=>t.textContent).join('')))}
  const out=new Map();for(const sh of [...wb.getElementsByTagName('sheet')]){const rel=[...rels.getElementsByTagName('Relationship')].find(x=>x.getAttribute('Id')===sh.getAttribute('r:id'));let target=rel.getAttribute('Target').replace(/^\//,'');if(!target.startsWith('xl/'))target='xl/'+target.replace(/^\.\//,'');const xml=parser.parseFromString(await zip.file(target).async('string'),'application/xml'),rows=[];for(const rr of [...xml.getElementsByTagName('row')]){const row=[];for(const c of [...rr.getElementsByTagName('c')]){const letters=((c.getAttribute('r')||'A1').match(/[A-Z]+/)||['A'])[0];let col=0;for(const ch of letters)col=col*26+ch.charCodeAt(0)-64;col--;const t=c.getAttribute('t'),raw=c.getElementsByTagName('v')[0]?.textContent||'';row[col]=t==='inlineStr'?[...c.getElementsByTagName('t')].map(x=>x.textContent).join(''):t==='s'?shared[Number(raw)]??'':raw}rows.push(row)}out.set(norm(sh.getAttribute('name')),rows)}return out
}

async function downloadOutput(){const people=activePeople(),alloc=new Map(people.map(p=>[p.id,allocation(p.id)])),used=new Set([...alloc.values()].flat().map(a=>a.center_id)),cols=state.centers.filter(c=>used.has(c.id)),fixed=5,first=fixed+1,last=fixed+cols.length,L=colName,excelDate=d=>d?{v:(Date.UTC(...d.split('-').map((x,i)=>i===1?x-1:+x))-Date.UTC(1899,11,30))/86400000,s:7}:'',legajo=id=>/^[1-9]\d{0,14}$/.test(String(id))?Number(id):String(id);
  const title=`Asignación de personal DMO · ${periodLabel().replace(/^./,c=>c.toUpperCase())}`,n=people.length,top=5,bottom=Math.max(top,top+n-1),matrix=[[{v:title,s:3}],[{v:'Faltan asignar:',s:5},{f:`COUNTIF(${L(last+2)}${top}:${L(last+2)}${bottom},"Falta")`,v:0,s:5}],[...Array(fixed-1).fill(''),{v:'Código centro',s:4},...cols.map(c=>({v:String(c.code),s:4}))],[...['Legajo','Apellido y nombres','Responsable','Fecha ingreso','Fecha baja'],...cols.map(c=>c.name),'Total','Estado'].map(v=>({v,s:1}))];
  people.forEach((p,i)=>{const r=top+i,pct=new Map();alloc.get(p.id).forEach(a=>pct.set(a.center_id,Math.round(((pct.get(a.center_id)||0)+Number(a.pct)/100)*1e6)/1e6));const total=[...pct.values()].reduce((s,x)=>s+x,0),ok=Math.abs(total-1)<1e-6;matrix.push([legajo(p.id),p.name,responsible(owner(p))?.name||'',excelDate(p.start_date),excelDate(p.end_date),...cols.map(c=>({v:pct.get(c.id)||0,s:2})),{f:`SUM(${L(first)}${r}:${L(last)}${r})`,v:total,s:6},{f:`IF(ROUND(${L(last+1)}${r},4)<>1,"Falta","Ok")`,v:ok?'Ok':'Falta',t:'str',s:8}]);if(!ok)matrix[1][1].v++});
  const detail=[['Periodo','Legajo','Nombre','Fecha alta','Fecha baja','Responsable principal','Código centro','Unidad','Centro','Tipo','Porcentaje']];people.forEach(p=>alloc.get(p.id).forEach(a=>{const c=center(a.center_id);detail.push([period,legajo(p.id),p.name,excelDate(p.start_date),excelDate(p.end_date),responsible(owner(p))?.name||'',c.code,c.unit,c.name,c.type,{v:Math.round(Number(a.pct)*1e4)/1e6,s:2}])}));detail[0]=detail[0].map(v=>({v,s:1}));
  const blob=await makeXlsx([{name:'Asignación',rows:matrix,widths:[10,32,24,12,12,...cols.map(()=>14),10,9],freeze:[fixed,4],filter:`A4:${L(last+2)}${bottom}`,heights:{4:48}},{name:'Detalle',rows:detail,widths:[10,10,32,12,12,24,14,12,28,12,12],freeze:[0,1],filter:`A1:K${detail.length}`}]);downloadBlob(blob,`DMO_Asignaciones_${period}.xlsx`);await audit('export',`Exportación mensual ${period}: ${n} personas, ${detail.length-1} asignaciones`);toast('Excel generado.')}
function xmlEsc(v){return String(v??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]))}
function colName(n){let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)}return s}
async function makeXlsx(sheets){
  const zip=new JSZip(),ct='application/vnd.openxmlformats-officedocument.spreadsheetml',rel='http://schemas.openxmlformats.org/officeDocument/2006/relationships';
  zip.file('[Content_Types].xml',`<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="${ct}.sheet.main+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="${ct}.worksheet+xml"/>`).join('')}<Override PartName="/xl/styles.xml" ContentType="${ct}.styles+xml"/></Types>`);
  zip.folder('_rels').file('.rels',`<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="${rel}/officeDocument" Target="xl/workbook.xml"/></Relationships>`);
  zip.folder('xl').file('workbook.xml',`<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="${rel}"><sheets>${sheets.map((s,i)=>`<sheet name="${xmlEsc(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets><calcPr calcId="191029" fullCalcOnLoad="1"/></workbook>`);
  zip.folder('xl').folder('_rels').file('workbook.xml.rels',`<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="${rel}/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${sheets.length+1}" Type="${rel}/styles" Target="styles.xml"/></Relationships>`);
  zip.folder('xl').file('styles.xml','<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="1"><numFmt numFmtId="164" formatCode="0.00%;-0.00%;&quot;-&quot;"/></numFmts><fonts count="5"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="10"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font><font><b/><sz val="14"/><color rgb="FF14282B"/><name val="Calibri"/></font><font><sz val="9"/><color rgb="FF7A8587"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF007E76"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="9"><xf/><xf fontId="1" fillId="2" applyFont="1" applyFill="1" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf numFmtId="164" applyNumberFormat="1"/><xf fontId="2" applyFont="1"/><xf fontId="3" applyFont="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf fontId="4" applyFont="1"/><xf numFmtId="164" fontId="4" applyNumberFormat="1" applyFont="1"/><xf numFmtId="14" applyNumberFormat="1"/><xf applyAlignment="1"><alignment horizontal="center"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
  const cell=(x,ref)=>{if(x===''||x==null)return'';const o=typeof x==='object'?x:{v:x},s=o.s?` s="${o.s}"`:'';if(o.f)return`<c r="${ref}"${s}${o.t?` t="${o.t}"`:''}><f>${xmlEsc(o.f)}</f><v>${xmlEsc(o.v)}</v></c>`;return typeof o.v==='number'?`<c r="${ref}"${s}><v>${o.v}</v></c>`:`<c r="${ref}" t="inlineStr"${s}><is><t>${xmlEsc(o.v)}</t></is></c>`};
  sheets.forEach((sh,i)=>{const[x,y]=sh.freeze||[0,0],pane=x||y?`<pane${x?` xSplit="${x}"`:''}${y?` ySplit="${y}"`:''} topLeftCell="${colName(x+1)}${y+1}" activePane="${x&&y?'bottomRight':y?'bottomLeft':'topRight'}" state="frozen"/>`:'',cols=sh.widths?`<cols>${sh.widths.map((w,ci)=>`<col min="${ci+1}" max="${ci+1}" width="${w}" customWidth="1"/>`).join('')}</cols>`:'',data=sh.rows.map((r,ri)=>`<row r="${ri+1}"${sh.heights?.[ri+1]?` ht="${sh.heights[ri+1]}" customHeight="1"`:''}>${r.map((v,ci)=>cell(v,colName(ci+1)+(ri+1))).join('')}</row>`).join('');zip.folder('xl').folder('worksheets').file(`sheet${i+1}.xml`,`<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"${i===0?' tabSelected="1"':''}>${pane}</sheetView></sheetViews><sheetFormatPr defaultRowHeight="15"/>${cols}<sheetData>${data}</sheetData>${sh.filter?`<autoFilter ref="${sh.filter}"/>`:''}</worksheet>`)});
  return zip.generateAsync({type:'blob',mimeType:`${ct}.sheet`})
}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

